// load 读取数据文件，返回顶层数组中的原始记录以及已解析的房间记录。
// 文件无法读取或不是合法数组时返回错误，绝不重置已有数据。
func (s *roomStore) load() ([]json.RawMessage, []room, error) {
	raw, err := os.ReadFile(s.path)
	if err != nil {
		return nil, nil, fmt.Errorf("读取房间数据失败: %w", err)
	}
	var records []json.RawMessage
	if err := json.Unmarshal(raw, &records); err != nil {
		return nil, nil, fmt.Errorf("房间数据不是合法的数组: %w", err)
	}
	rooms := make([]room, 0, len(records))
	for i, rec := range records {
		var r room
		if err := json.Unmarshal(rec, &r); err != nil {
			return nil, nil, fmt.Errorf("第 %d 条房间记录无法解析: %w", i+1, err)
		}
		rooms = append(rooms, r)
	}
	return records, rooms, nil
}

