1	package main
2	
3	import (
4		"context"
5		"crypto/rand"
6		_ "embed"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"flag"
11		"fmt"
12		"io"
13		"net"
14		"net/http"
15		"os"
16		"os/signal"
17		"path/filepath"
18		"strings"
19		"sync"
20		"syscall"
21		"time"
22	)
23	
24	const product = "ScoreArena"
25	const resourceName = "rooms"
26	
27	//go:embed index.html
28	var indexPage []byte
29	
30	// roomConfig 是创建房间时接受的配置；指针字段用于区分“缺失”与“零值”。
31	type roomConfig struct {
32		Name        string `json:"name"`
33		Game        string `json:"game"`
34		Capacity    int    `json:"capacity"`
35		TurnSeconds int    `json:"turnSeconds"`
36	}
37	
38	type room struct {
39		ID          string `json:"id"`
40		Name        string `json:"name"`
41		Game        string `json:"game"`
42		Capacity    int    `json:"capacity"`
43		TurnSeconds int    `json:"turnSeconds"`
44		Status      string `json:"status"`
45		Visibility  string `json:"visibility"`
46		CreatedAt   string `json:"createdAt"`
47	}
48	
49	type roomStore struct {
50		mu   sync.Mutex
51		path string
52	}
53	
54	func newRoomStore(path string) *roomStore {
55		return &roomStore{path: path}
56	}
57	
58	// load 读取数据文件，返回顶层数组中的原始记录以及已占用的房间编号。
59	// 文件无法读取或不是合法数组时返回错误，绝不重置已有数据。
60	// 数组中的非对象元素原样保留（兼容历史记录及其附带字段）。
61	func (s *roomStore) load() ([]json.RawMessage, map[string]bool, error) {
62		raw, err := os.ReadFile(s.path)
63		if err != nil {
64			return nil, nil, fmt.Errorf("读取房间数据失败: %w", err)
65		}
66		var records []json.RawMessage
67		if err := json.Unmarshal(raw, &records); err != nil {
68			return nil, nil, fmt.Errorf("房间数据不是合法的数组: %w", err)
69		}
70		used := make(map[string]bool, len(records))
71		for _, rec := range records {
72			var probe struct {
73				ID string `json:"id"`
74			}
75			if err := json.Unmarshal(rec, &probe); err == nil && probe.ID != "" {
76				used[probe.ID] = true
77			}
78		}
79		return records, used, nil
80	}
81	
82	// create 校验配置、写入新记录并返回保存后的房间。
83	func (s *roomStore) create(cfg roomConfig) (room, int, error) {
84		if code, msg, ok := validateConfig(cfg); !ok {
85			return room{}, code, errors.New(msg)
86		}
87	
88		s.mu.Lock()
89		defer s.mu.Unlock()
90	
91		records, used, err := s.load()
92		if err != nil {
93			return room{}, http.StatusInternalServerError, err
94		}
95	
96		now := time.Now()
97		newRoom := room{
98			ID:          uniqueRoomID(used),
99			Name:        cfg.Name,
100			Game:        cfg.Game,
101			Capacity:    cfg.Capacity,
102			TurnSeconds: cfg.TurnSeconds,
103			Status:      "waiting",
104			Visibility:  "public",
105			CreatedAt:   now.UTC().Format(time.RFC3339),
106		}
107	
108		encoded, err := json.Marshal(newRoom)
109		if err != nil {
110			return room{}, http.StatusInternalServerError, fmt.Errorf("序列化房间记录失败: %w", err)
111		}
112		records = append(records, encoded)
113		if err := s.writeAtomic(records); err != nil {
114			return room{}, http.StatusInternalServerError, err
115		}
116		return newRoom, http.StatusCreated, nil
117	}
118	
119	// writeAtomic 先写临时文件再重命名，避免保存失败时破坏原有数据。
120	func (s *roomStore) writeAtomic(records []json.RawMessage) error {
121		payload, err := json.MarshalIndent(records, "", "  ")
122		if err != nil {
123			return fmt.Errorf("序列化房间数据失败: %w", err)
124		}
125		payload = append(payload, '\n')
126	
127		dir := filepath.Dir(s.path)
128		tmp, err := os.CreateTemp(dir, ".rooms-*.tmp")
129		if err != nil {
130			return fmt.Errorf("创建临时数据文件失败: %w", err)
131		}
132		tmpName := tmp.Name()
133		cleanup := func() { _ = os.Remove(tmpName) }
134	
135		if _, err := tmp.Write(payload); err != nil {
136			_ = tmp.Close()
137			cleanup()
138			return fmt.Errorf("写入房间数据失败: %w", err)
139		}
140		if err := tmp.Sync(); err != nil {
141			_ = tmp.Close()
142			cleanup()
143			return fmt.Errorf("同步房间数据失败: %w", err)
144		}
145		if err := tmp.Close(); err != nil {
146			cleanup()
147			return fmt.Errorf("关闭临时数据文件失败: %w", err)
148		}
149		if err := os.Rename(tmpName, s.path); err != nil {
150			cleanup()
151			return fmt.Errorf("保存房间数据失败: %w", err)
152		}
153		return nil
154	}
155	
156	func uniqueRoomID(used map[string]bool) string {
157		var b [16]byte
158		for {
159			if _, err := rand.Read(b[:]); err != nil {
160				panic(fmt.Errorf("生成房间编号失败: %w", err))
161			}
162			id := hex.EncodeToString(b[:])
163			if !used[id] {
164				return id
165			}
166		}
167	}
168	
169	// validateConfig 执行全部字段校验，返回 http 状态码与具体原因。
170	// 所有字段都必须明确提交且合法，不使用任何默认值。
171	func validateConfig(cfg roomConfig) (int, string, bool) {
172		name := strings.TrimSpace(cfg.Name)
173		if name == "" {
174			return http.StatusBadRequest, "房间名称不能为空", false
175		}
176		if len([]rune(name)) > 40 {
177			return http.StatusBadRequest, "房间名称去掉首尾空白后不能超过 40 个字符", false
178		}
179	
180		switch cfg.Game {
181		case "gomoku":
182			if cfg.Capacity != 2 {
183				return http.StatusBadRequest, "五子棋的人数上限固定为 2 人", false
184			}
185		case "ludo":
186			if cfg.Capacity < 2 || cfg.Capacity > 4 {
187				return http.StatusBadRequest, "飞行棋的人数上限必须为 2 至 4 人", false
188			}
189		default:
190			return http.StatusBadRequest, "未知游戏规则，目前仅支持 gomoku（五子棋）和 ludo（飞行棋）", false
191		}
192	
193		if cfg.TurnSeconds != 0 && (cfg.TurnSeconds < 10 || cfg.TurnSeconds > 600) {
194			return http.StatusBadRequest, "每步时间限制只能为 0（不限时）或 10 至 600 秒之间的整数", false
195		}
196		return 0, "", true
197	}
198	
199	func respond(w http.ResponseWriter, status int, value any) {
200		w.Header().Set("Content-Type", "application/json; charset=utf-8")
201		w.WriteHeader(status)
202		_ = json.NewEncoder(w).Encode(value)
203	}
204	
205	func methodNotAllowed(w http.ResponseWriter, allow string) {
206		w.Header().Set("Content-Type", "application/json; charset=utf-8")
207		w.Header().Set("Allow", allow)
208		w.WriteHeader(http.StatusMethodNotAllowed)
209		_ = json.NewEncoder(w).Encode(map[string]string{"error": "method not allowed"})
210	}
211	
212	func run() error {
213		if len(os.Args) < 2 {
214			printHelp()
215			return errors.New("expected serve or --help")
216		}
217		if os.Args[1] == "--help" || os.Args[1] == "-h" {
218			printHelp()
219			return nil
220		}
221		if os.Args[1] != "serve" {
222			return errors.New("expected serve or --help")
223		}
224		args := flag.NewFlagSet("score-arena serve", flag.ContinueOnError)
225		args.SetOutput(os.Stdout)
226		host := args.String("host", "127.0.0.1", "address to bind")
227		port := args.Int("port", 8080, "port to bind; 0 selects an available port")
228		data := args.String("data-dir", "data", "directory for local records")
229		if err := args.Parse(os.Args[2:]); errors.Is(err, flag.ErrHelp) {
230			return nil
231		} else if err != nil {
232			return err
233		}
234		if args.NArg() != 0 {
235			return errors.New("unexpected positional argument")
236		}
237		if *port < 0 || *port > 65535 {
